mapper.select:
where m.status = '0'
and (m.med_code like concat('%', #{keyword}, '%') or m.med_name like concat('%', #{keyword}, '%') or m.trade_name like concat('%', #{keyword}, '%') or m.approval_no like concat('%', #{keyword}, '%'))
order by m.med_id limit #{limit}


where m.status = '0' and ifnull(st.total_qty, 0) < m.stock_min
order by (m.stock_min - ifnull(st.total_qty, 0)) desc, m.med_id
limit #{limit}
